function Overview({create,download,token,setToken,connection,connect,dashboard}:{create:()=>void;download:()=>void;token:string;setToken:(v:string)=>void;connection:string;connect:()=>void;dashboard:DashboardData|null}){const storage=dashboard?.components.storage, vms=dashboard?.components.vms, hardware=dashboard?.components.hardware, updates=dashboard?.components.updates;return <><div className="kicker">SERVER OVERVIEW</div><Title title={dashboard?'Your Bedrock server':'Connect to your server'} copy={dashboard?'Live health and workload information from the authenticated Bedrock API.':'Enter a local API token. It stays in memory and is cleared after this connection attempt.'} action={dashboard?<button className="primary" onClick={connect}>Refresh</button>:undefined}/><div className={`connection ${connection}`}><span className="connectiondot"/><div><strong>{connection==='connected'?'Connected to Bedrock':connection==='loading'?'Connecting…':connection==='error'?'Server unavailable':'Authentication required'}</strong><p>{connection==='error'?'Check that this page is served by your Bedrock server and that the token is active.':'No sample health values are presented as live server data.'}</p></div>{!dashboard&&<><label><span>API token</span><input type="password" value={token} onChange={e=>setToken(e.target.value)} onKeyDown={e=>e.key==='Enter'&&token&&connect()} autoComplete="off"/></label><button className="primary" disabled={!token||connection==='loading'} onClick={connect}>Connect</button></>}</div>{dashboard&&<><div className="health"><b>{dashboard.partial?'!':'✓'}</b><div><strong>{dashboard.partial?'Some services need attention':'Live server data available'}</strong><p>{dashboard.partial?'Available sections remain usable while unavailable services are isolated.':'All reported dashboard components responded successfully.'}</p></div><small>Authenticated API</small></div><div className="metrics"><Metric l="PROCESSOR" v={hardware?.status==='available'?String(hardware.data?.logical_processors??'—'):'—'} s="logical processors" w="0%" tip="Processor capacity reported by your Bedrock server."/><Metric l="MEMORY" v={hardware?.status==='available'?`${Math.round(Number(hardware.data?.memory_total_bytes??0)/1073741824)} GB`:'—'} s="installed" w="0%" tip="Installed memory reported by your Bedrock server."/><Metric l="STORAGE" v={storage?.status==='available'?String(storage.data?.overall??'Unknown'):'Unavailable'} s={storage?.status==='available'?`${String(storage.data?.disk_count??0)} disks`:'service offline'} w="0%" tip="Current protected-storage health from Bedrock."/><Metric l="VIRTUAL MACHINES" v={vms?.status==='available'?`${String(vms.data?.running??0)} running`:'Unavailable'} s={vms?.status==='available'?`${String(vms.data?.total??0)} managed`:'service offline'} w="0%" tip="Managed virtual machine status from Bedrock."/></div><div className="twocol"><div className="panel"><Section title="Update status" copy="Signed Bedrock release channel"/><p>{updates?.status==='available'?String(updates.data?.status??'Unknown'):'Update service unavailable'}</p></div><div className="panel"><Section title="Quick actions" copy="Available management areas"/><div className="quick"><button onClick={download}>⇩ <span><b>Get Bedrock</b><small>Create verified installation media</small></span>›</button><button onClick={create}>▣ <span><b>View virtual machines</b><small>Live lifecycle and resource status</small></span>›</button></div></div></div></>}</>}
function Metric({l,v,s,w,tip}:{l:string,v:string,s:string,w:string,tip:string}){return <div className="metric"><label>{l} <Tip>{tip}</Tip></label><strong>{v}</strong><small>{s}</small><div className="bar"><i style={{width:w}}/></div></div>}
function Section({title,copy}:{title:string,copy:string}){return <div className="section"><div><h2>{title}</h2><p>{copy}</p></div></div>}
function VMPassthroughEditor({data,candidates,token,setCandidates,notify}:{data:VmFeed|null;candidates:PassthroughFeed|null;token:string;setCandidates:(value:PassthroughFeed|null)=>void;notify:(value:string)=>void}){type Kind='gpu'|'usb';type Operation='assign'|'remove';const stopped=data?.domains.filter(vm=>vm.state==='shut off')??[];const [name,setName]=useState(''),[kind,setKind]=useState<Kind>('usb'),[operation,setOperation]=useState<Operation>('assign'),[selection,setSelection]=useState(''),[review,setReview]=useState(''),[confirmation,setConfirmation]=useState(''),[working,setWorking]=useState(false),[error,setError]=useState('');const assignment=candidates?.assignments.find(item=>item.vm===name&&item.kind===kind),gpu=candidates?.gpus.find(item=>item.id===selection),devices=operation==='remove'?assignment?.devices??[]:kind==='gpu'?gpu?.devices??[]:selection?[selection]:[],ordered=[...devices].sort(),label=kind.toUpperCase(),reviewPhrase=name&&ordered.length?`REVIEW ${label} PASSTHROUGH VM ${name} DEVICES ${ordered.join(',')}`:'',actionPhrase=reviewPhrase?`${operation.toUpperCase()} ${label} PASSTHROUGH VM ${name} DEVICES ${ordered.join(',')}`:'';const reset=(nextName=name,nextKind=kind,nextOperation=operation)=>{setName(nextName);setKind(nextKind);setOperation(nextOperation);setSelection('');setReview('');setConfirmation('');setError('')};const save=async()=>{if(!reviewPhrase||review!==reviewPhrase||confirmation!==actionPhrase)return;setWorking(true);setError('');try{const response=await fetch(`/api/v1/vms/${name}/passthrough`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({schema:1,kind,devices:ordered,operation,review_confirmation:review,confirmation})});if(!response.ok)throw new Error(response.status===422?'The VM or hardware safety state changed.':'Bedrock rejected the passthrough change.');const refreshed=await fetch('/api/v1/virtualization/passthrough-candidates',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});if(!refreshed.ok)throw new Error('Passthrough changed, but refreshed status is unavailable.');setCandidates(await refreshed.json() as PassthroughFeed);reset(name,kind,operation);notify(`${label} passthrough ${operation==='assign'?'assigned':'removed'}`)}catch(reason){setError(reason instanceof Error?reason.message:'Passthrough change failed.')}finally{setWorking(false)}};if(!data)return null;if(!candidates)return <div className="panel resource-editor"><Section title="Hardware passthrough" copy="Candidate inventory unavailable"/><Empty text="Safe passthrough candidates could not be loaded."/></div>;const choices=kind==='gpu'?candidates.gpus.map(item=>({id:item.id,label:`${item.vendor} ${item.device_id} · group ${item.devices.join(', ')}`})):candidates.usb_devices.map(item=>({id:item.id,label:`USB ${item.vendor_id}:${item.product_id} · ${item.id}`}));return <div className="panel resource-editor"><Section title="Hardware passthrough" copy="Offline GPU and USB assignment with hardware safety revalidation"/><div className="note"><span><b>High-impact change.</b> Bedrock excludes the boot GPU, hubs, storage, input, unauthorized, and host-critical USB devices. GPU assignment moves the complete IOMMU group away from the host.</span></div>{stopped.length===0?<Empty text="Shut down a VM before changing passthrough devices."/>:<><div className="resource-fields attachment-fields"><label>Virtual machine<select value={name} onChange={event=>reset(event.target.value)}><option value="">Choose a shut-off VM</option>{stopped.map(vm=><option key={vm.name}>{vm.name}</option>)}</select></label><label>Device type<select value={kind} onChange={event=>reset(name,event.target.value as Kind)}><option value="usb">USB</option><option value="gpu">GPU group</option></select></label><label>Action<select value={operation} onChange={event=>reset(name,kind,event.target.value as Operation)}><option value="assign">Assign</option><option value="remove">Remove</option></select></label><label>Safe selection{operation==='remove'?<input readOnly value={assignment?assignment.devices.join(', '):''} placeholder="No assignment"/>:<select disabled={!name} value={selection} onChange={event=>{setSelection(event.target.value);setReview('');setConfirmation('')}}><option value="">Choose {kind}</option>{choices.map(item=><option key={item.id} value={item.id}>{item.label}</option>)}</select>}</label></div>{name&&operation==='remove'&&!assignment&&<p className="form-error" role="alert">This VM has no {kind.toUpperCase()} passthrough assignment.</p>}{reviewPhrase&&<><label className="resource-confirm">Review and type <b>{reviewPhrase}</b><input autoComplete="off" value={review} onChange={event=>setReview(event.target.value)}/></label><label className="resource-confirm">Then type <b>{actionPhrase}</b><input autoComplete="off" value={confirmation} onChange={event=>setConfirmation(event.target.value)} onKeyDown={event=>event.key==='Enter'&&review===reviewPhrase&&confirmation===actionPhrase&&save()}/></label>{error&&<p className="form-error" role="alert">{error}</p>}<button className="primary" disabled={working||review!==reviewPhrase||confirmation!==actionPhrase} onClick={save}>{working?'Revalidating hardware…':`${operation==='assign'?'Assign':'Remove'} ${label} passthrough`}</button></>}</>}</div>}
function VMs({data,connected,token,setData,notify}:{data:VmFeed|null;connected:boolean;token:string;setData:(value:VmFeed|null)=>void;notify:(value:string)=>void}){type PowerOperation='start'|'stop'|'restart'|'force-stop';type SnapshotOperation='create'|'restore'|'delete';type Selection={kind:'power';name:string;operation:PowerOperation}|{kind:'snapshot';name:string;operation:SnapshotOperation;snapshot:string}|{kind:'admin';name:string;operation:'clone';target:string}|{kind:'admin';name:string;operation:'delete'};const [selected,setSelected]=useState<Selection|null>(null),[snapshotName,setSnapshotName]=useState(''),[cloneName,setCloneName]=useState(''),[confirmation,setConfirmation]=useState(''),[working,setWorking]=useState(false),[error,setError]=useState('');const phrase=selected?(selected.kind==='power'?`${selected.operation==='force-stop'?'FORCE STOP':selected.operation.toUpperCase()} VM ${selected.name}`:selected.kind==='snapshot'?`${selected.operation.toUpperCase()} SNAPSHOT ${selected.snapshot} FOR VM ${selected.name}`:selected.operation==='clone'?`CLONE VM ${selected.name} AS ${selected.target}`:`DELETE VM ${selected.name} AND STORAGE`):'';const choose=(value:Selection)=>{setSelected(value);setConfirmation('');setError('')};const run=async()=>{if(!selected||confirmation!==phrase)return;setWorking(true);setError('');try{const snapshot=selected.kind==='snapshot',admin=selected.kind==='admin';const endpoint=admin?(selected.operation==='clone'?`/api/v1/vms/${selected.name}/clone`:`/api/v1/vms/${selected.name}`):`/api/v1/vms/${selected.name}/${snapshot?'snapshots':'power'}`;const body=snapshot?{schema:1,snapshot:selected.snapshot,operation:selected.operation,confirmation}:admin?(selected.operation==='clone'?{schema:1,name:selected.target,confirmation}:{schema:1,confirmation}):{schema:1,operation:selected.operation,confirmation};const response=await fetch(endpoint,{method:admin&&selected.operation==='delete'?'DELETE':'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});if(!response.ok)throw new Error(response.status===422?'The VM state changed or Bedrock could not complete the action.':'Bedrock rejected the VM action.');const refreshed=await fetch('/api/v1/vms',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});if(!refreshed.ok)throw new Error('The action completed, but refreshed VM status is unavailable.');setData(await refreshed.json() as VmFeed);notify(admin?`VM ${selected.operation} completed`:snapshot?`Snapshot ${selected.operation} completed`:`VM ${selected.operation.replace('-',' ')} completed`);setSelected(null);setSnapshotName('');setCloneName('')}catch(reason){setError(reason instanceof Error?reason.message:'VM action failed.')}finally{setWorking(false)}};const validSnapshot=/^[a-z][a-z0-9-]{0,30}[a-z0-9]$/.test(snapshotName),validClone=/^[a-z][a-z0-9-]{0,30}[a-z0-9]$/.test(cloneName)&&!data?.domains.some(vm=>vm.name===cloneName);return <><Title title="Virtual machines" copy="Live lifecycle, resource, snapshot, image, and network status."/><LiveState connected={connected} available={!!data} noun="virtual machine inventory"/><div className="note"><Tip>A virtual machine is a computer made from software. It runs its own operating system without changing Bedrock.</Tip><span><b>Protected controls.</b> Power, snapshots, cloning, and recoverable deletion require exact confirmation. Storage-changing actions are available only while a VM is shut off.</span></div>{data&&<div className="table vmtable"><div className="thead"><b>NAME</b><b>STATUS</b><b>RESOURCES</b><b>ATTACHMENTS</b><b>SNAPSHOTS</b><b>ACTIONS</b></div>{data.domains.length===0?<Empty text="No virtual machines are registered."/>:data.domains.map(vm=><div className="trow" key={vm.name}><span><b className="os">VM</b><strong>{vm.name}</strong></span><span><i className={vm.state==='running'?'live':'off'}/>{vm.state}</span><span>{vm.vcpus} vCPU · {(vm.memory_mib/1024).toFixed(vm.memory_mib%1024?1:0)} GB</span><span>{vm.image_attachments.length} images · {vm.network_attachments.length} networks</span><span className="snapshot-list">{vm.snapshots.length===0?<small>None</small>:vm.snapshots.map(snapshot=><span key={snapshot}><b>{snapshot}</b>{vm.state==='shut off'&&<><button onClick={()=>choose({kind:'snapshot',name:vm.name,operation:'restore',snapshot})}>Restore</button><button className="danger" onClick={()=>choose({kind:'snapshot',name:vm.name,operation:'delete',snapshot})}>Delete</button></>}</span>)}</span><span className="vm-actions">{vm.state==='shut off'&&<><button onClick={()=>choose({kind:'power',name:vm.name,operation:'start'})}>Start</button><label className="snapshot-create"><span>New snapshot name</span><input aria-label={`New snapshot name for ${vm.name}`} placeholder="pre-upgrade" value={snapshotName} onChange={event=>setSnapshotName(event.target.value)}/><button disabled={!validSnapshot||vm.snapshots.includes(snapshotName)} onClick={()=>choose({kind:'snapshot',name:vm.name,operation:'create',snapshot:snapshotName})}>Create snapshot</button></label><label className="snapshot-create"><span>Clone as</span><input aria-label={`Clone name for ${vm.name}`} placeholder="copy-vm" value={cloneName} onChange={event=>setCloneName(event.target.value)}/><button disabled={!validClone||cloneName===vm.name} onClick={()=>choose({kind:'admin',name:vm.name,operation:'clone',target:cloneName})}>Clone</button></label><button className="danger" onClick={()=>choose({kind:'admin',name:vm.name,operation:'delete'})}>Delete VM and storage</button></>}{vm.state==='running'&&<><button onClick={()=>choose({kind:'power',name:vm.name,operation:'stop'})}>Stop</button><button onClick={()=>choose({kind:'power',name:vm.name,operation:'restart'})}>Restart</button><button className="danger" onClick={()=>choose({kind:'power',name:vm.name,operation:'force-stop'})}>Force stop</button></>}{vm.state==='paused'&&<button className="danger" onClick={()=>choose({kind:'power',name:vm.name,operation:'force-stop'})}>Force stop</button>}</span></div>)}</div>}{selected&&<div className="shade" role="presentation" onMouseDown={event=>event.target===event.currentTarget&&!working&&setSelected(null)}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="vm-action-title"><header><h2 id="vm-action-title">{selected.operation.replace('-',' ')} {selected.kind==='snapshot'?`${selected.snapshot} on `:selected.kind==='admin'&&selected.operation==='clone'?`${selected.name} as ${selected.target}`:''}{selected.kind==='admin'&&selected.operation==='clone'?'':selected.name}</h2><button aria-label="Close" disabled={working} onClick={()=>setSelected(null)}>×</button></header><p>{selected.kind==='power'&&selected.operation==='force-stop'?'Force stop can cause guest data loss. Use it only when a graceful stop is impossible.':selected.kind==='snapshot'&&selected.operation==='restore'?'Restoring replaces the VM disk state with this snapshot. Changes made afterward will be lost.':selected.kind==='admin'&&selected.operation==='delete'?'The VM and its managed disk will leave active inventory and move to recoverable quarantine. Confirm only after checking backups.':'Bedrock will recheck the managed VM and verify the requested final state.'}</p><label>Type <b>{phrase}</b><input autoFocus autoComplete="off" value={confirmation} onChange={event=>setConfirmation(event.target.value)} onKeyDown={event=>event.key==='Enter'&&confirmation===phrase&&run()}/></label>{error&&<p className="form-error" role="alert">{error}</p>}<footer><button disabled={working} onClick={()=>setSelected(null)}>Cancel</button><button className="primary" disabled={working||confirmation!==phrase} onClick={run}>{working?'Working…':'Confirm action'}</button></footer></section></div>}</>}
function Storage({data,connected}:{data:StorageFeed|null;connected:boolean}){const capacity=(bytes:number)=>bytes>=1e12?`${(bytes/1e12).toFixed(1)} TB`:`${Math.max(1,Math.round(bytes/1e9))} GB`;const pools=data?.software_raid.zfs.pools??[];const arrays=data?.software_raid.md_arrays??[];return <><Title title="Storage" copy="Live capacity, disk health, RAID state, and rebuild progress."/><LiveState connected={connected} available={!!data} noun="storage health"/><div className="note"><span><b>Read-only view.</b> Create, expand, replace, scrub, export, and import controls will appear after authenticated mutation routes are available.</span></div>{data&&<><div className="metrics hardwaremetrics"><Metric l="OVERALL" v={data.overall} s="storage health" w={data.overall==='healthy'?'100%':data.overall==='attention'?'50%':'25%'} tip="Combined disk, software RAID, ZFS, and hardware RAID health."/><Metric l="RAW CAPACITY" v={capacity(data.disks.reduce((sum,disk)=>sum+disk.size_bytes,0))} s={`${data.disks.length} physical disk${data.disks.length===1?'':'s'}`} w="100%" tip="Total detected physical-disk capacity without exposing device paths or serial numbers."/><Metric l="SOFTWARE RAID" v={String(arrays.length+pools.length)} s={`${arrays.length} Linux RAID · ${pools.length} ZFS`} w={arrays.length+pools.length?'100%':'0%'} tip="Managed Linux RAID arrays and ZFS pools reported by Bedrock."/><Metric l="HARDWARE RAID" v={String(data.hardware_raid.controller_count)} s={`${data.hardware_raid.full_visibility_count} fully visible`} w={data.hardware_raid.controller_count?`${Math.round(data.hardware_raid.full_visibility_count/data.hardware_raid.controller_count*100)}%`:'0%'} tip="Hardware RAID monitoring depends on a supported vendor management tool."/></div><div className="twocol"><div className="panel"><Section title="Protected storage" copy={`${arrays.length+pools.length} software-managed group${arrays.length+pools.length===1?'':'s'}`}/>{arrays.length+pools.length===0?<Empty text="No software RAID arrays or ZFS pools were reported."/>:<>{arrays.map(array=><div className="drive" key={`md-${array.name}`}><b>MD</b><div><strong>{array.name}</strong><p>{array.level} · {array.active_members} of {array.expected_members} members · {array.state}</p></div><span className={array.health==='healthy'?'ready':'waiting'}>{array.sync.action?`${array.sync.action} ${array.sync.percent.toFixed(0)}%`:array.health}</span></div>)}{pools.map(pool=><div className="drive" key={`zfs-${pool.name}`}><b>ZFS</b><div><strong>{pool.name}</strong><p>{capacity(pool.allocated_bytes)} used · {capacity(pool.free_bytes)} free · {pool.health}</p></div><span className={pool.status==='healthy'?'ready':'waiting'}>{pool.status}</span></div>)}</>}</div><div className="panel"><Section title="RAID controller visibility" copy={`${data.hardware_raid.controller_count} controller${data.hardware_raid.controller_count===1?'':'s'} detected`}/><div className="hardwaretotals"><span><b>{data.hardware_raid.full_visibility_count}</b> fully monitored</span><span><b>{data.hardware_raid.attention_count}</b> need attention</span><span><b>{Math.max(0,data.hardware_raid.controller_count-data.hardware_raid.full_visibility_count)}</b> limited visibility</span></div></div></div><div className="panel"><Section title="Physical drives" copy={`${data.disks.filter(d=>d.smart.health==='healthy').length} healthy of ${data.disks.length}`}/>{data.disks.length===0?<Empty text="No physical disks were reported."/>:data.disks.map((disk,index)=><div className="drive" key={`${disk.model}-${index}`}><b>▱</b><div><strong>{disk.model||`Disk ${index+1}`}</strong><p>{capacity(disk.size_bytes)} · {disk.transport||'unknown connection'} · SMART {disk.smart.health}</p></div><span>{disk.smart.temperature_c===null?'—':`${disk.smart.temperature_c}°C`}</span></div>)}</div></>}</>}
function Images({data,connected}:{data:ImageFeed|null;connected:boolean}){const size=(bytes:number)=>bytes>=1073741824?`${(bytes/1073741824).toFixed(1)} GiB`:`${Math.max(1,Math.round(bytes/1048576))} MiB`;return <><Title title="Image library" copy="Verified operating system installers and disk images ready for virtual machines."/><LiveState connected={connected} available={!!data} noun="image inventory"/><div className="note"><span><b>Read-only view.</b> Import and conversion controls will appear after authenticated mutation routes are available.</span></div>{data&&<div className="panel"><Section title="Verified images" copy={`${data.images.length} available`}/>{data.images.length===0?<Empty text="No verified images are available."/>:data.images.map(image=><div className="drive" key={image.name}><b className="os">{image.type.toUpperCase().slice(0,4)}</b><div><strong>{image.name}</strong><p>{image.type.toUpperCase()} · {size(image.size_bytes)} · SHA-256 {image.sha256.slice(0,12)}…</p></div><span className="ready">{image.converted?'Converted':'Imported'}</span></div>)}</div>}<div className="note"><b>macOS guests are not supported.</b> Bedrock does not provide Apple software or offer macOS VM creation on current hosts.</div></>}
function Apps({data,connected}:{data:AppFeed|null;connected:boolean}){return <><Title title="Apps" copy="Isolated services running with fixed resource and network limits."/><LiveState connected={connected} available={!!data} noun="application status"/>{data&&<div className="panel"><Section title="Installed apps" copy={`${data.apps.length} configured`}/>{data.apps.length===0?<Empty text="No isolated applications are installed."/>:data.apps.map(app=><div className="drive" key={app.id}><b>⬡</b><div><strong>{app.name}</strong><p>{app.resources.cpus} CPU · {app.resources.memory_mib} MiB · {app.network==='bridge'?`${app.port_count} published port${app.port_count===1?'':'s'}`:'No network'}</p></div><span className="ready">{app.update_policy==='notify'?'Update alerts':'Manual updates'}</span></div>)}</div>}</>}
function Backups({data,connected}:{data:BackupFeed|null;connected:boolean}){const weekday=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return <><Title title="Backup" copy="Encrypted plans, schedules, retention, and last successful protection."/><LiveState connected={connected} available={!!data} noun="backup status"/>{data&&<div className="panel"><Section title="Backup plans" copy={`${data.plans.length} configured`}/>{data.plans.length===0?<Empty text="No encrypted backup plans are configured."/>:data.plans.map(plan=><div className="drive" key={plan.id}><b>↻</b><div><strong>{plan.name}</strong><p>{plan.schedule.frequency==='daily'?'Daily':`${weekday[plan.schedule.weekday??0]} weekly`} at {String(plan.schedule.hour_utc).padStart(2,'0')}:00 UTC · {plan.kind}</p></div><span className={plan.has_snapshot?'ready':'waiting'}>{plan.has_snapshot?(plan.last_success_unix?`Protected ${new Date(plan.last_success_unix*1000).toLocaleDateString()}`:'Protected'):'Never run'}</span></div>)}</div>}</>}
function Hardware({data,connected}:{data:HardwareData|null;connected:boolean}){return <><Title title="Hardware" copy="Capacity and compatibility reported by this Bedrock server."/><LiveState connected={connected} available={!!data} noun="hardware inventory"/>{data&&<><div className="metrics hardwaremetrics"><Metric l="PROCESSOR" v={`${data.cpu.logical_processors} threads`} s={data.cpu.model} w="100%" tip="Processor model and logical thread count reported by Bedrock."/><Metric l="MEMORY" v={`${Math.round(data.memory.total_bytes/1073741824)} GB`} s="installed" w="100%" tip="Total installed memory available to the host."/><Metric l="DISKS" v={String(data.disks.length)} s={`${(data.disks.reduce((sum,disk)=>sum+disk.size_bytes,0)/1e12).toFixed(1)} TB raw`} w="100%" tip="Physical disks detected without exposing their device paths or serial numbers."/><Metric l="VIRTUALIZATION" v={data.cpu.virtualization_supported?'Ready':'Unavailable'} s={data.cpu.virtualization} w={data.cpu.virtualization_supported?'100%':'0%'} tip="Hardware acceleration capability reported by the processor."/></div><div className="twocol"><div className="panel"><Section title="Graphics" copy={`${data.gpus.length} adapter${data.gpus.length===1?'':'s'}`}/>{data.gpus.length===0?<Empty text="No supported graphics adapters were reported."/>:data.gpus.map((gpu,index)=><div className="drive" key={`${gpu.vendor}-${index}`}><b>▣</b><div><strong>{gpu.vendor} graphics</strong><p>{gpu.driver} driver · {gpu.boot_vga?'Host display':'Secondary adapter'}</p></div><span className={gpu.recognized_vendor?'ready':'waiting'}>{gpu.recognized_vendor?'Recognized':'Limited'}</span></div>)}</div><div className="panel"><Section title="Connections" copy="Privacy-safe totals"/><div className="hardwaretotals"><span><b>{data.networks.length}</b> network links</span><span><b>{data.storage_controllers.length}</b> storage controllers</span><span><b>{data.usb_device_count}</b> USB devices</span></div></div></div></>}</>}
function LiveState({connected,available,noun}:{connected:boolean;available:boolean;noun:string}){return <div className={`connection ${connected&&available?'connected':connected?'error':'idle'}`}><span className="connectiondot"/><div><strong>{!connected?'Connect from Overview':available?'Live server data':'Service unavailable'}</strong><p>{!connected?`Authenticate once to load ${noun}.`:available?'This view came from the authenticated Bedrock API.':`Bedrock is connected, but ${noun} could not be loaded.`}</p></div></div>}
function Empty({text}:{text:string}){return <div className="empty"><b>○</b><span>{text}</span></div>}
function Download({notify}:{notify:(s:string)=>void}){const [os,setOs]=useState('Windows');return <><button className="back">← Back to Bedrock</button><div className="download"><div><div className="kicker">Bedrock INSTALLER · v0.1.0</div><h1>Your server starts here.</h1><p>Turn an ordinary computer into private storage and a home for your virtual machines.</p>{['Download Bedrock Installer|A small tool that prepares your USB drive.','Choose a USB drive or DVD image|8 GB or larger is recommended.','Start the server and follow along|The guided setup explains every decision.'].map((x,i)=>{const a=x.split('|');return <div className="step" key={x}><b>{i+1}</b><span><strong>{a[0]}</strong><small>{a[1]}</small></span></div>})}</div><div className="installer"><div className="ilog"><b>H</b><span><strong>Bedrock Installer</strong><small>Create your installer safely</small></span></div><label>Your computer</label><div className="segments">{['Windows','macOS','Linux'].map(x=><button className={os===x?'sel':''} onClick={()=>setOs(x)} key={x}>{x}</button>)}</div><button className="writer" onClick={()=>notify(`Bedrock Installer for ${os} is being prepared`)}>⇩ Download for {os}</button><p>Version 0.1.0 · Open source · <a href="https://github.com" target="_blank">View on GitHub ↗</a></p><hr/><button className="iso" onClick={()=>notify('Direct ISO download is being prepared')}>Download ISO directly <Tip>Use this with another USB-writing app, a virtual machine, or burn it to a DVD.</Tip></button></div></div><div className="requirements"><span>✓ 64-bit Intel or AMD</span><span>✓ 8 GB RAM minimum</span><span>✓ 32 GB system drive</span><span>✓ Wired network recommended</span></div></>}
function Remote({data,connected}:{data:RemoteDeviceFeed|null;connected:boolean}){const active=data?.devices.filter(device=>!device.revoked&&!device.expired).length??0;const seen=(value:number|null)=>value===null?'Never connected':`Last seen ${new Date(value*1000).toLocaleString()}`;return <><Title title="Remote access" copy="Trusted computers authorized to reach this Bedrock server." action={<span className="securebadge">● Device-specific trust</span>}/><LiveState connected={connected} available={!!data} noun="trusted-device status"/><div className="note"><span><b>Read-only view.</b> Secure pairing and revocation controls will appear after authenticated mutation routes are available.</span></div>{data&&<><div className="metrics hardwaremetrics"><Metric l="TRUSTED" v={String(active)} s="active devices" w={data.devices.length?`${Math.round(active/data.devices.length*100)}%`:'0%'} tip="Devices whose trust has not expired or been revoked."/><Metric l="REVOKED" v={String(data.devices.filter(device=>device.revoked).length)} s="access removed" w="0%" tip="Revoked devices cannot establish a new Bedrock session."/><Metric l="EXPIRED" v={String(data.devices.filter(device=>device.expired&&!device.revoked).length)} s="renewal required" w="0%" tip="Expired device credentials must be paired again before use."/></div><div className="panel devices"><Section title="Trusted devices" copy={`${data.devices.length} registered`}/>{data.devices.length===0?<Empty text="No remote devices are paired."/>:data.devices.map(device=>{const status=device.revoked?'Revoked':device.expired?'Expired':'Trusted';return <div className="device" key={device.id}><b>⌁</b><div><strong>{device.name}</strong><p>{seen(device.last_seen_unix)} · Added {new Date(device.created_unix*1000).toLocaleDateString()} · Expires {new Date(device.expires_unix*1000).toLocaleDateString()}</p></div><span className={status==='Trusted'?'ready':'waiting'}>{status}</span></div>})}</div></>}<div className="note"><Tip>Remote access uses device-specific credentials. Revoking one device does not require changing trust for the others.</Tip><span><b>Private by design.</b> Public keys and fingerprints are never returned to this interface.</span></div></>}
function Activity({tasks,alerts,audit,connected}:{tasks:TaskFeed|null;alerts:AlertFeed|null;audit:AuditFeed|null;connected:boolean}){const available=[tasks,alerts,audit].filter(Boolean).length;const progress=(task:TaskFeed['tasks'][number])=>Math.min(100,Math.round(task.progress.current/task.progress.total*100));return <><Title title="Activity" copy="Live work, health alerts, and security-relevant history."/><LiveState connected={connected} available={available>0} noun="activity feeds"/>{connected&&available>0&&available<3&&<div className="note"><span><b>Partial data.</b> Available feeds remain visible while an unavailable service is isolated.</span></div>}<div className="twocol"><div className="panel"><Section title="Tasks" copy={tasks?`${tasks.tasks.length} retained`:'Unavailable'}/>{tasks?(tasks.tasks.length===0?<Empty text="No recent tasks."/>:tasks.tasks.map(task=><div className="drive" key={task.id}><b>◔</b><div><strong>{task.kind.replaceAll('-',' ')}</strong><p>{task.progress.current} of {task.progress.total} {task.progress.unit} · Updated {new Date(task.updated_unix*1000).toLocaleString()}</p><div className="milestonebar"><i style={{width:`${progress(task)}%`}}/></div></div><span className={task.state==='succeeded'?'ready':task.state==='running'?'waiting':''}>{task.state}</span></div>)):<Empty text="Task status is unavailable."/>}</div><div className="panel"><Section title="Active alerts" copy={alerts?`${alerts.alerts.length} require review`:'Unavailable'}/>{alerts?(alerts.alerts.length===0?<Empty text="No active health alerts."/>:alerts.alerts.map(alert=><div className="drive" key={alert.id}><b>!</b><div><strong>{alert.kind.replaceAll('-',' ')}</strong><p>First seen {new Date(alert.first_seen_unix*1000).toLocaleString()} · Updated {new Date(alert.last_seen_unix*1000).toLocaleString()}</p></div><span className="waiting">{alert.severity}</span></div>)):<Empty text="Alert status is unavailable."/>}</div></div><div className="panel"><Section title="Audit history" copy={audit?`${audit.events.length} recent events`:'Unavailable'}/>{audit?(audit.events.length===0?<Empty text="No audit events have been recorded."/>:audit.events.map(event=><div className="drive" key={event.id}><b>✓</b><div><strong>{event.category} · {event.action.replaceAll('-',' ')}</strong><p>{new Date(event.occurred_unix*1000).toLocaleString()} · Identifiers and command details are excluded</p></div><span className={event.outcome==='succeeded'?'ready':'waiting'}>{event.outcome}</span></div>)):<Empty text="Audit history is unavailable."/>}</div></>}
function Settings({data,connected,token,setData,notify}:{data:SettingsFeed|null;connected:boolean;token:string;setData:(value:SettingsFeed|null)=>void;notify:(value:string)=>void}){const [saving,setSaving]=useState(false),[betaAck,setBetaAck]=useState(false),[error,setError]=useState('');const update=async(setting:'automatic_checks'|'channel',value:boolean|'stable'|'beta')=>{setSaving(true);setError('');try{const response=await fetch('/api/v1/settings',{method:'PUT',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({schema:1,setting,value,beta_risk_acknowledged:value==='beta'&&betaAck})});if(!response.ok)throw new Error(response.status===409?'This change conflicts with an earlier request. Try again.':'Bedrock rejected the policy change.');const refreshed=await fetch('/api/v1/settings',{headers:{Authorization:`Bearer ${token}`},cache:'no-store'});if(!refreshed.ok)throw new Error('The change succeeded, but the refreshed policy is unavailable.');setData(await refreshed.json() as SettingsFeed);setBetaAck(false);notify('Update policy saved')}catch(reason){setError(reason instanceof Error?reason.message:'Policy change failed.')}finally{setSaving(false)}};return <><Title title="Settings" copy="Update and privacy policy for this Bedrock server."/><LiveState connected={connected} available={!!data} noun="settings policy"/>{data&&<><div className="note"><span><b>Safe updates.</b> Bedrock may check automatically, but installation always requires an administrator action after signature verification.</span></div>{error&&<div className="note settings-error" role="alert"><span><b>Change not saved.</b> {error}</span></div>}<div className="panel"><Section title="System policy" copy="Validated and applied by Bedrock"/><div className="drive settings-row"><b>↻</b><div><strong>Release channel</strong><p>{data.updates.channel==='stable'?'Stable releases only':'Beta releases accepted with explicit risk acknowledgement'}</p>{data.updates.channel!=='beta'&&<label className="risk"><input type="checkbox" checked={betaAck} onChange={event=>setBetaAck(event.target.checked)}/> I understand beta releases may be unstable.</label>}</div><div className="settings-actions"><span className={data.updates.channel==='stable'?'ready':'waiting'}>{data.updates.channel}</span>{data.updates.channel==='stable'?<button disabled={saving||!betaAck} onClick={()=>update('channel','beta')}>Use beta</button>:<button disabled={saving} onClick={()=>update('channel','stable')}>Use stable</button>}</div></div><div className="drive settings-row"><b>◔</b><div><strong>Automatic update checks</strong><p>{data.updates.setup_choice_recorded?'Administrator choice recorded':'Waiting for first-run administrator choice'}</p></div><div className="settings-actions"><span className={data.updates.automatic_checks?'ready':'waiting'}>{data.updates.automatic_checks?'Enabled':'Disabled'}</span><button disabled={saving} onClick={()=>update('automatic_checks',!data.updates.automatic_checks)}>{data.updates.automatic_checks?'Disable':'Enable'}</button></div></div><div className="drive"><b>↓</b><div><strong>Automatic installation</strong><p>Updates require an explicit administrator action after signature verification.</p></div><span className="ready">Never</span></div><div className="drive"><b>○</b><div><strong>Telemetry</strong><p>Bedrock does not send usage or diagnostic data automatically.</p></div><span className="ready">Disabled</span></div></div></>}</>}
function Users({data,connected}:{data:UserFeed|null;connected:boolean}){return <><Title title="Users" copy="Managed storage accounts, groups, and credential-rotation status."/><LiveState connected={connected} available={!!data} noun="user and group inventory"/><div className="note"><span><b>Read-only view.</b> Account, group, membership, and credential controls will appear after authenticated mutation routes are available.</span></div>{data&&<><div className="metrics hardwaremetrics"><Metric l="USERS" v={String(data.users.length)} s="managed accounts" w={data.users.length?'100%':'0%'} tip="Accounts created through Bedrock storage management."/><Metric l="GROUPS" v={String(data.groups.length)} s="access groups" w={data.groups.length?'100%':'0%'} tip="Groups used to grant dataset and share access."/><Metric l="ROTATED" v={String(data.users.filter(user=>user.credential_rotated_unix!==null).length)} s="credentials renewed" w={data.users.length?`${Math.round(data.users.filter(user=>user.credential_rotated_unix!==null).length/data.users.length*100)}%`:'0%'} tip="Accounts whose managed storage credential has been rotated at least once."/></div><div className="twocol"><div className="panel"><Section title="Accounts" copy={`${data.users.length} configured`}/>{data.users.length===0?<Empty text="No managed storage accounts."/>:data.users.map(user=><div className="drive" key={user.name}><b>♧</b><div><strong>{user.name}</strong><p>Created {new Date(user.created_unix*1000).toLocaleDateString()} · Credential generation {user.credential_generation}</p></div><span className={user.credential_rotated_unix!==null?'ready':'waiting'}>{user.credential_rotated_unix===null?'Not rotated':`Rotated ${new Date(user.credential_rotated_unix*1000).toLocaleDateString()}`}</span></div>)}</div><div className="panel"><Section title="Groups" copy={`${data.groups.length} configured`}/>{data.groups.length===0?<Empty text="No access groups."/>:data.groups.map(group=><div className="drive" key={group.name}><b>◎</b><div><strong>{group.name}</strong><p>Created {new Date(group.created_unix*1000).toLocaleDateString()}</p></div><span>{group.member_count} member{group.member_count===1?'':'s'}</span></div>)}</div></div></>}<div className="note"><Tip>Member identities and share permissions are intentionally excluded from this summary.</Tip><span><b>Credentials stay private.</b> Passwords and hashes are never returned to the interface.</span></div></>}
function Help(){const root='https://github.com/DEADish1/bedrock-os/blob/codex/latest-update/';const links=[['Install Bedrock','docs/INSTALLATION.md','Prepare verified media and install safely.'],['First-run setup','docs/FIRST-RUN-SETUP.md','Configure the administrator, network, time, and updates.'],['Administration','docs/ADMINISTRATION.md','Operate storage, guests, apps, backups, and updates.'],['Troubleshooting','docs/TROUBLESHOOTING.md','Diagnose problems without risking data.'],['Privacy and diagnostics','docs/DIAGNOSTICS.md','Review and create a consent-gated redacted support bundle.'],['Support policy','SUPPORT.md','Understand support boundaries and security reporting.']];return <><Title title="Help" copy="Bedrock operating guides and safe recovery paths."/><div className="panel helplinks"><Section title="Documentation" copy="Version-controlled project guidance"/>{links.map(([title,path,copy])=><a className="drive" href={`${root}${path}`} target="_blank" rel="noreferrer" key={path}><b>↗</b><div><strong>{title}</strong><p>{copy}</p></div><span>Open</span></a>)}</div><div className="note"><Tip>A diagnostic bundle excludes user files, credentials, pairing state, API tokens, command arguments, and raw logs.</Tip><span><b>Need support?</b> Start with Troubleshooting, then review the diagnostic bundle before sharing it.</span></div></>}
function ProjectStatus(){const versions=[
 {v:'0.1',name:'Product definition',state:'Complete',done:8,total:8,items:['Brand and product language','Interactive product prototype','Versioned roadmap and update log','Hardware and architecture decisions']},
 {v:'0.2',name:'Bootable foundation',state:'Current',done:7,total:8,items:['Debian 13 base and kernel policy','UEFI boot and diagnostics','Immutable A/B system disk','Bootable ISO and USB image','Signed updates and rollback','Hardware discovery','Reproducible CI builds','Physical and VM platform tests']},
 {v:'0.3',name:'Installer and setup',state:'In progress',done:6,total:8,items:['Windows, macOS, and Linux installer','Safe target-drive confirmation','Verified media writing','First-run server setup']},
 {v:'0.4',name:'Storage and NAS',state:'Complete',done:10,total:10,items:['Storage pools and disk health','Software RAID and RAID-Z','Hardware RAID controller support','SMB, NFS, and Time Machine','Datasets, snapshots, and quotas','Users, groups, ACLs, and credentials','Guided create and expansion','Scrub, export, and safe import','Drive-failure replacement and rebuild','Interruption and integrity recovery']},
 {v:'0.5',name:'VMs and images',state:'Acceptance pending',done:8,total:8,items:['KVM/QEMU integration','VM lifecycle and snapshots','GPU and USB passthrough','Image import and conversion']},
 {v:'0.6',name:'Interface and API',state:'Planned',done:0,total:7,items:['Authenticated server API','Real telemetry and tasks','Complete management areas','Accessibility and end-to-end tests']},
 {v:'0.7',name:'Remote clients',state:'In progress',done:1,total:8,items:['Encrypted remote transport threat model','QR and code pairing','Google identity option','Signed Windows and macOS clients']},
 {v:'0.8',name:'Backup and recovery',state:'In progress',done:4,total:7,items:['Consent-gated redacted diagnostics','Configuration recovery','Encrypted backup and restore','Actionable health notifications','Application isolation','UPS and maintenance safety']},
 {v:'0.9',name:'Release candidate',state:'Planned',done:0,total:9,items:['Upgrade and failure testing','Security review and SBOM','Signed release candidate','Documentation and beta triage']},
 {v:'1.0',name:'Ready to ship',state:'Ship gate',done:0,total:8,items:['Signed OS and installers','Signed desktop clients','Public source and releases','Final acceptance and launch']}
 ];return <><Title title="Project status" copy="The path from product definition to a fully functional, ready-to-ship Bedrock 1.0." action={<span className="versionbadge">Current version <b>0.2.0-dev</b></span>}/><div className="progresshero"><div><div className="kicker">RELEASE PROGRESS</div><h2>Guarded VM administration expanded</h2><p>48 of 80 tracked release requirements are complete.</p></div><div className="bigprogress"><span style={{width:'60%'}}/></div><b>60%</b></div><div className="roadmap">{versions.map(x=><article className={x.state==='Current'?'current':''} key={x.v}><header><span>v{x.v}</span><div><h2>{x.name}</h2><p>{x.state} · {x.done} of {x.total} complete</p></div><b>{x.state==='Current'||x.state==='In progress'||x.state==='Acceptance pending'?'IN PROGRESS':x.state==='Complete'?'COMPLETE':x.state==='Ship gate'?'SHIP GATE':'PLANNED'}</b></header><div className="milestonebar"><i style={{width:`${x.done/x.total*100}%`}}/></div><ul>{x.items.map((item,i)=><li className={i<x.done?'complete':''} key={item}><span>{i<x.done?'✓':'○'}</span>{item}</li>)}</ul></article>)}</div><div className="updatepanel"><div><div className="kicker">LATEST UPDATE · 2026-09-08</div><h2>Virtual machine creation</h2><p>Authenticated administrators can now create capacity-checked stopped UEFI guests with TPM 2.0, then attach verified installation media and start them through separate confirmed actions.</p></div><div><strong>Physical acceptance gates remain</strong><p>v0.2 still needs VMware, Hyper-V, physical Intel, and physical AMD boot reports. v0.3 needs disposable USB and system-disk evidence; v0.5 needs Linux and Windows guest evidence.</p></div></div><div className="note"><Tip>The complete checklist and change history live in PROJECT-ROADMAP.md and CHANGELOG.md in the project source.</Tip><span><b>Reviewable by design.</b> Each release must update the checklist, update log, website status, version metadata, and artifact checksums.</span></div></>}
